package com.mod.htgt6.minecraft1202.Module.World.Modern;
import com.mod.htgt6.common.util.*;import com.mod.htgt6.minecraft1202.Module.Data.Modern.NetherFossilData120;import cpw.mods.fml.common.IWorldGenerator;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import java.util.*;import net.minecraft.init.Blocks;import net.minecraft.world.*;import net.minecraft.world.chunk.*;import net.minecraftforge.event.world.ChunkEvent;
public final class NetherFossilGenerator120 implements IWorldGenerator{private static final OfficialJigsawRegistry120 R=new OfficialJigsawRegistry120("nether_fossils",0);private static final String[] T=new String[14];static{for(int i=0;i<T.length;i++)T[i]="minecraft:nether_fossils/fossil_"+(i+1);}
 public void generate(Random ignored,int cx,int cz,World w,IChunkProvider a,IChunkProvider b){if(w.isRemote||w.provider.dimensionId!=-1||!w.getWorldInfo().isMapFeaturesEnabled())return;NetherFossilData120 d=NetherFossilData120.get(w);NetherFossilData120.Start s=d.start(cx,cz);if(s==null&&StructurePlacement120.isCandidate(w.getSeed(),cx,cz,StructurePlacement120.NETHER_FOSSIL)){Chunk c=WorldSafety.getLoadedChunk(w,cx,cz);if(c!=null){Random r=new Random(seed(w.getSeed(),cx,cz));int y=32+r.nextInt(Math.max(1,w.getActualHeight()-34));for(;y>32;y--)if(c.getBlock(8,y,8)==Blocks.air&&c.getBlock(8,y-1,8)==Blocks.soul_sand)break;if(y>32){String t=T[r.nextInt(T.length)];int rot=r.nextInt(4);s=d.record(cx,cz,y,seed(w.getSeed(),cx,cz),t,rot);}}}replay(w,d,cx,cz);if(s!=null)backfill(w,d,s,cx,cz);}
 @SubscribeEvent public void chunkLoad(ChunkEvent.Load e){World w=e.world;if(w!=null&&!w.isRemote&&w.provider.dimensionId==-1&&e.getChunk().isTerrainPopulated)replay(w,NetherFossilData120.get(w),e.getChunk().xPosition,e.getChunk().zPosition);}
 private static void replay(World w,NetherFossilData120 d,int cx,int cz){for(NetherFossilData120.Start s:d.starts()){JigsawPlacementRuntime120.Template t=R.template(s.template);Box q=box(s,t);if(d.done(s,cx,cz)||!hit(q,cx,cz))continue;FuturaAncientCityGenerator120.placeTemplateAtOrigin(w,OfficialJigsawRegistry120.templateResource(s.template),q.x,s.y,q.z,s.rotation,cx,cz,Collections.<String>emptyList(),false);d.doneSet(s,cx,cz);}}
 private static void backfill(World w,NetherFossilData120 d,NetherFossilData120.Start s,int ax,int az){Box q=box(s,R.template(s.template));for(int x=q.x>>4;x<=q.maxX>>4;x++)for(int z=q.z>>4;z<=q.maxZ>>4;z++){if(x==ax&&z==az)continue;Chunk c=WorldSafety.getLoadedChunk(w,x,z);if(c!=null&&c.isTerrainPopulated)replay(w,d,x,z);}}
 private static Box box(NetherFossilData120.Start s,JigsawPlacementRuntime120.Template t){int w=(s.rotation&1)==0?t.sizeX:t.sizeZ,z=(s.rotation&1)==0?t.sizeZ:t.sizeX;int ox=(s.x<<4)+8-w/2,oz=(s.z<<4)+8-z/2;return new Box(ox,oz,ox+w-1,oz+z-1);}private static boolean hit(Box b,int x,int z){int a=x<<4,c=z<<4;return b.maxX>=a&&b.x<=a+15&&b.maxZ>=c&&b.z<=c+15;}private static long seed(long s,int x,int z){return s^(long)x*341873128712L^(long)z*132897987541L^14357921L;}
 public static void validateTemplates(){for(String t:T){if(R.template(t)==null)throw new IllegalStateException("Missing "+t);FuturaAncientCityGenerator120.validateTemplateResource(OfficialJigsawRegistry120.templateResource(t));}}public static int templateCount(){return T.length;}static final class Box{final int x,z,maxX,maxZ;Box(int x,int z,int X,int Z){this.x=x;this.z=z;maxX=X;maxZ=Z;}}}
